import type { CheckIn } from '@/types/domain'
import { useI18n, type MessageKey } from '@/i18n'
import { fmtDate } from '@/i18n/format'

/**
 * Connection trend — two thin sparklines, no composite score, no verdict.
 * A screen reader gets the table, not the SVG (blueprint 04 §13).
 */
export function ConnectionTrend({ checkins }: { checkins: CheckIn[] }) {
  const { t, locale } = useI18n()
  const points = [...checkins].sort((a, b) => a.date.localeCompare(b.date)).slice(-14)
  if (points.length === 0) return null

  return (
    <div className="stack stack--tight">
      <p className="chip chip--lavender" style={{ alignSelf: 'flex-start' }}>
        {t(describeKey(points))}
      </p>

      <svg
        viewBox={`0 0 ${Math.max(points.length - 1, 1) * 24} 60`}
        width="100%"
        height="72"
        aria-hidden="true"
        style={{ overflow: 'visible' }}
      >
        <Line points={points.map((p) => p.connection)} color="var(--primary)" />
        <Line points={points.map((p) => p.energy)} color="var(--blue)" dashed />
      </svg>

      <div className="row" style={{ gap: 'var(--space-3)', fontSize: 12 }}>
        <span className="row" style={{ gap: 6 }}>
          <span style={{ width: 14, height: 3, background: 'var(--primary)', borderRadius: 3 }} />
          {t('trend.connected')}
        </span>
        <span className="row" style={{ gap: 6 }}>
          <span
            style={{
              width: 14,
              height: 3,
              borderRadius: 3,
              background:
                'repeating-linear-gradient(90deg, var(--blue) 0 4px, transparent 4px 7px)',
            }}
          />
          {t('trend.energy')}
        </span>
      </div>

      {/* The accessible alternative is a real table, not an aria-label paragraph. */}
      <details>
        <summary style={{ cursor: 'pointer', fontSize: 13, fontWeight: 700 }}>
          {t('trend.seeNumbers')}
        </summary>
        <div className="table-scroll" style={{ marginTop: 8 }}>
        <table>
          <caption className="visually-hidden">{t('trend.tableCaption')}</caption>
          <thead>
            <tr>
              <th scope="col" style={cellHead}>
                {t('common.date')}
              </th>
              <th scope="col" style={cellHead}>
                {t('trend.energy')}
              </th>
              <th scope="col" style={cellHead}>
                {t('trend.connected')}
              </th>
            </tr>
          </thead>
          <tbody>
            {[...points].reverse().map((p) => (
              <tr key={p.id}>
                <th scope="row" style={cell}>
                  {fmtDate(p.date, 'd MMM', locale)}
                </th>
                <td style={cell}>{t('trend.scaleOf', { n: p.energy })}</td>
                <td style={cell}>{t('trend.scaleOf', { n: p.connection })}</td>
              </tr>
            ))}
          </tbody>
        </table>
        </div>
      </details>
    </div>
  )
}

const cellHead: React.CSSProperties = {
  textAlign: 'left',
  padding: '4px 6px',
  borderBottom: '1px solid var(--border)',
  fontWeight: 700,
}
const cell: React.CSSProperties = {
  textAlign: 'left',
  padding: '4px 6px',
  borderBottom: '1px solid var(--border)',
  fontWeight: 400,
}

function Line({ points, color, dashed }: { points: number[]; color: string; dashed?: boolean }) {
  if (points.length === 1) points = [points[0]!, points[0]!]
  const d = points
    .map((v, i) => `${i === 0 ? 'M' : 'L'} ${i * 24} ${60 - ((v - 1) / 4) * 52 - 4}`)
    .join(' ')
  return (
    <>
      <path
        d={d}
        fill="none"
        stroke={color}
        strokeWidth="2.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeDasharray={dashed ? '5 4' : undefined}
      />
      {points.map((v, i) => (
        <circle key={i} cx={i * 24} cy={60 - ((v - 1) / 4) * 52 - 4} r="2.6" fill={color} />
      ))}
    </>
  )
}

/**
 * Picks a reflection phrase — blueprint 04 §1, "no judgment visualization".
 * Returns a key, never text, and never a percentage, a verdict about the
 * relationship, or a judgement about either person.
 */
export function describeKey(points: CheckIn[]): MessageKey {
  const recent = points.slice(-4)
  const older = points.slice(0, -4)
  const avg = (xs: CheckIn[], k: 'connection' | 'energy') =>
    xs.length ? xs.reduce((s, x) => s + x[k], 0) / xs.length : 0

  const conn = avg(recent, 'connection')
  const energy = avg(recent, 'energy')
  const prev = avg(older, 'connection')

  if (older.length >= 2 && conn - prev >= 0.6) return 'trend.closer'
  if (energy <= 2.2) return 'trend.lowEnergy'
  if (older.length >= 2 && prev - conn >= 0.6) return 'trend.distance'
  if (conn >= 3.5) return 'trend.stable'
  return 'trend.mixed'
}
