import { useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { format, subDays } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import {
  Card,
  EmptyState,
  Field,
  PARTNER_VISIBILITY_OPTIONS,
  Scale,
  Sheet,
  VisibilityBadge,
  VISIBILITY_OPTIONS,
} from '@/components/ui'
import { useSession } from '@/app/session'
import { byCreatedDesc, useOwned } from '@/db/hooks'
import { db, newEnvelope, setVisibility, softDelete } from '@/db/db'
import type { Appreciation, CheckIn, Need, RepairRequest, Topic, Visibility } from '@/types/domain'
import { ConnectionTrend } from './ConnectionTrend'
import { useI18n, useT, type MessageKey } from '@/i18n'
import { fmtDate } from '@/i18n/format'

type NewThing = 'checkin' | 'need' | 'appreciation' | 'topic' | 'repair' | null

/**
 * Arah hubungan (blueprint 03 §3, 04 §11).
 *
 * There is deliberately no single relationship score anywhere on this screen —
 * only trends, lists, and prompts. `soloMode` renders the same machinery for a
 * single user, minus anything that implies a partner.
 */
export default function Relationship({ soloMode = false }: { soloMode?: boolean }) {
  const { t, locale } = useI18n()
  const { profile, partner } = useSession()
  const me = profile?.id
  const [params, setParams] = useSearchParams()
  const [sheet, setSheet] = useState<NewThing>((params.get('baru') as NewThing) ?? null)

  const checkins = useOwned<CheckIn>('checkins', me, (a, b) => b.date.localeCompare(a.date))
  const needs = useOwned<Need>('needs', me, byCreatedDesc)
  const appreciations = useOwned<Appreciation>('appreciations', me, byCreatedDesc)
  const topics = useOwned<Topic>('topics', me, byCreatedDesc)
  const repairs = useOwned<RepairRequest>('repairs', me, byCreatedDesc)

  if (!profile || !me) return null

  function open(kind: NewThing) {
    setSheet(kind)
    if (kind === null && params.has('baru')) {
      params.delete('baru')
      setParams(params, { replace: true })
    }
  }

  const recent = (checkins ?? []).filter((c) => c.date >= format(subDays(new Date(), 30), 'yyyy-MM-dd'))
  const openNeeds = (needs ?? []).filter((n) => !n.resolvedAt)
  const openTopics = (topics ?? []).filter((t) => t.status !== 'talked')
  const openRepairs = (repairs ?? []).filter((r) => r.status !== 'complete')

  return (
    <div className="stack">
      <h1>{soloMode ? t('rel.titleSolo') : t('rel.title')}</h1>
      <p className="card__hint">
        {soloMode
          ? t('rel.subtitleSolo')
          : t('rel.subtitle')}
      </p>

      <Card
        title={t('rel.checkin')}
        icon="checkin"
        action={
          <button className="btn btn--sm" onClick={() => open('checkin')}>
            <Icon name="plus" size={16} /> {t('rel.checkinFill')}
          </button>
        }
        hint={t('rel.checkinHint')}
      >
        {recent.length === 0 ? (
          <EmptyState icon="checkin" title={t('rel.noCheckin')} hint={t('rel.noCheckinHint')} />
        ) : (
          <ConnectionTrend checkins={recent} />
        )}
      </Card>

      <Card
        title={soloMode ? t('rel.needsSolo') : t('rel.needs')}
        icon="heart"
        action={
          <button className="btn btn--sm" onClick={() => open('need')}>
            <Icon name="plus" size={16} /> {t('common.add')}
          </button>
        }
      >
        {openNeeds.length === 0 ? (
          <EmptyState icon="heart" title={t('rel.noNeeds')} hint={t('rel.noNeedsHint')} />
        ) : (
          <ul className="list">
            {openNeeds.map((n) => (
              <li key={n.id} className="list__item">
                <span className="grow">{n.text}</span>
                {/* The owner gets the control; everyone else gets the badge.
                    Showing both put "Cuma aku" on the row twice. */}
                {n.ownerProfileId !== me && <VisibilityBadge visibility={n.visibility} />}
                {n.ownerProfileId === me && (
                  <ShareMenu store="needs" id={n.id} me={me} current={n.visibility} soloMode={soloMode} />
                )}
                {n.ownerProfileId === me && (
                  <button
                    className="btn btn--ghost btn--sm btn--icon"
                    onClick={() => db.needs.update(n.id, { resolvedAt: new Date().toISOString() })}
                  >
                    <Icon name="check" size={16} label={t('rel.markDiscussed')} />
                  </button>
                )}
              </li>
            ))}
          </ul>
        )}
      </Card>

      {!soloMode && (
        <>
          <Card
            title={t('rel.gratitude')}
            icon="date"
            action={
              <button className="btn btn--sm" onClick={() => open('appreciation')}>
                <Icon name="plus" size={16} /> {t('rel.gratitudeWrite')}
              </button>
            }
            hint={t('rel.gratitudeCount', { n: (appreciations ?? []).length })}
          >
            {(appreciations ?? []).length === 0 ? (
              <EmptyState icon="date" title={t('rel.noGratitude')} hint={t('rel.noGratitudeHint')} />
            ) : (
              <ul className="list">
                {(appreciations ?? []).slice(0, 5).map((a) => (
                  <li key={a.id} className="list__item">
                    <Icon name="date" size={18} />
                    <span className="grow">{a.text}</span>
                    <VisibilityBadge visibility={a.visibility} />
                  </li>
                ))}
              </ul>
            )}
          </Card>

          <Card
            title={t('rel.topics')}
            icon="checkin"
            action={
              <button className="btn btn--sm" onClick={() => open('topic')}>
                <Icon name="plus" size={16} /> {t('common.add')}
              </button>
            }
          >
            {openTopics.length === 0 ? (
              <EmptyState icon="checkin" title={t('rel.noTopics')} />
            ) : (
              <ul className="list">
                {openTopics.map((topic) => (
                  <li key={topic.id} className="list__item">
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{topic.title}</strong>
                      {topic.scheduledAt && (
                        <span className="card__hint">
                          {fmtDate(topic.scheduledAt, 'EEEE, d MMM', locale)}
                        </span>
                      )}
                    </span>
                    <span className={`chip ${topic.status === 'scheduled' ? 'chip--blue' : ''}`}>
                      {topic.status === 'scheduled'
                        ? t('today.scheduled')
                        : topic.status === 'parked'
                          ? t('rel.parked')
                          : t('today.notYet')}
                    </span>
                    <button
                      className="btn btn--ghost btn--sm btn--icon"
                      onClick={() => db.topics.update(topic.id, { status: 'talked' })}
                    >
                      <Icon name="check" size={16} label={t('rel.talked')} />
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </Card>

          <Card
            title={t('rel.repair')}
            icon="repair"
            action={
              <button className="btn btn--sm" onClick={() => open('repair')}>
                <Icon name="plus" size={16} /> {t('rel.repairSend')}
              </button>
            }
            hint={t('rel.repairHint')}
          >
            {openRepairs.length === 0 ? (
              <EmptyState icon="consent" title={t('home.noTasks')} />
            ) : (
              <ul className="list">
                {openRepairs.map((r) => (
                  <li key={r.id} className="list__item">
                    <span className="grow stack stack--tight">
                      <span>{r.message}</span>
                      <span className="card__hint">{t(`rel.repair.${r.status}` as const)}</span>
                    </span>
                    {r.status === 'waiting' && (
                      <button
                        className="btn btn--soft btn--sm"
                        onClick={() => db.repairs.update(r.id, { status: 'accepted' })}
                      >
                        {t('rel.repairOk')}
                      </button>
                    )}
                    <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('repairs', r.id, me)}>
                      <Icon name="close" size={16} label={t('common.delete')} />
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </Card>
        </>
      )}

      <p className="disclaimer">{t('rel.disclaimer')}</p>

      <NewSheet kind={sheet} onClose={() => open(null)} me={me} partnerName={partner?.displayName} soloMode={soloMode} />
    </div>
  )
}

/** Owner-only visibility switch. Rendered next to the object it controls. */
function ShareMenu({
  store,
  id,
  me,
  current,
  soloMode,
}: {
  store: 'needs'
  id: string
  me: string
  current: Visibility
  soloMode: boolean
}) {
  const t = useT()
  if (soloMode) return null
  return (
    <label className="row" style={{ gap: 4 }}>
      <span className="visually-hidden">{t('rel.whoCanSeeThis')}</span>
      <select
        value={current}
        style={{ width: 'auto', minHeight: 36, fontSize: 12 }}
        onChange={(e) => setVisibility(store, id, me, e.target.value as Visibility)}
      >
        {VISIBILITY_OPTIONS.map((v) => (
          <option key={v} value={v}>
            {t(`vis.opt.${v}` as const)}
          </option>
        ))}
      </select>
    </label>
  )
}

function NewSheet({
  kind,
  onClose,
  me,
  partnerName,
  soloMode,
}: {
  kind: NewThing
  onClose: () => void
  me: string
  partnerName?: string
  soloMode: boolean
}) {
  const t = useT()
  const [energy, setEnergy] = useState<1 | 2 | 3 | 4 | 5>()
  const [connection, setConnection] = useState<1 | 2 | 3 | 4 | 5>()
  const [stress, setStress] = useState('')
  const [text, setText] = useState('')
  const [visibility, setVis] = useState<Visibility>('private')
  const [saving, setSaving] = useState(false)

  function reset() {
    setEnergy(undefined)
    setConnection(undefined)
    setStress('')
    setText('')
    setVis('private')
  }

  async function save() {
    setSaving(true)
    try {
      if (kind === 'checkin' && energy && connection) {
        await db.checkins.add({
          ...newEnvelope(me, 'C3_relationship', { visibility }),
          kind: 'checkin',
          date: format(new Date(), 'yyyy-MM-dd'),
          energy,
          connection,
          ...(stress.trim() ? { stressContext: stress.trim() } : {}),
        } as never)
      } else if (kind === 'need' && text.trim()) {
        await db.needs.add({
          ...newEnvelope(me, 'C3_relationship', { visibility }),
          kind: 'need',
          text: text.trim(),
        } as never)
      } else if (kind === 'appreciation' && text.trim()) {
        await db.appreciations.add({
          ...newEnvelope(me, 'C3_relationship', { visibility: 'shared' }),
          kind: 'appreciation',
          text: text.trim(),
        } as never)
      } else if (kind === 'topic' && text.trim()) {
        await db.topics.add({
          ...newEnvelope(me, 'C2_shared_ops'),
          kind: 'topic',
          title: text.trim(),
          status: 'open',
        } as never)
      } else if (kind === 'repair' && text.trim()) {
        await db.repairs.add({
          ...newEnvelope(me, 'C2_shared_ops'),
          kind: 'repair',
          message: text.trim(),
          status: 'waiting',
        } as never)
      }
      reset()
      onClose()
    } finally {
      setSaving(false)
    }
  }

  const titleKey = (k: Exclude<NewThing, null>): MessageKey =>
    k === 'need' && soloMode ? 'rel.sheet.needSolo' : (`rel.sheet.${k}` as const)

  const canSave =
    kind === 'checkin' ? Boolean(energy && connection) : text.trim().length > 0

  return (
    <Sheet open={kind !== null} onClose={onClose} title={kind ? t(titleKey(kind)) : ''}>
      <div className="stack">
        {kind === 'checkin' && (
          <>
            <Scale legend={t('rel.energyQ')} value={energy} onChange={setEnergy} lowLabel={t('rel.energyLow')} highLabel={t('rel.energyHigh')} />
            <Scale
              legend={
                soloMode
                  ? t('rel.connQSolo')
                  : t('rel.connQ', { name: partnerName ?? t('rel.partner') })
              }
              value={connection}
              onChange={setConnection}
              lowLabel={t('rel.connLow')}
              highLabel={t('rel.connHigh')}
            />
            <Field label={t('rel.stressQ')} hint={t('common.optional')}>
              {(p) => <textarea {...p} value={stress} onChange={(e) => setStress(e.target.value)} />}
            </Field>
          </>
        )}

        {kind !== 'checkin' && kind !== null && (
          <Field label={t(titleKey(kind))}>
            {(p) => (
              <textarea
                {...p}
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder={
                  kind === 'repair' ? t('rel.repairPlaceholder') : ''
                }
              />
            )}
          </Field>
        )}

        {(kind === 'checkin' || kind === 'need') && !soloMode && (
          <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
            <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{t('common.whoCanSee')}</legend>
            <div className="choices">
              {PARTNER_VISIBILITY_OPTIONS.map((v) => (
                <button
                  key={v}
                  type="button"
                  role="radio"
                  aria-checked={visibility === v}
                  className="choice"
                  onClick={() => setVis(v)}
                >
                  <span className="stack stack--tight">
                    <span className="choice__title">{t(`vis.opt.${v}` as const)}</span>
                    <span className="choice__desc">{t(`vis.opt.${v}.desc` as const)}</span>
                  </span>
                </button>
              ))}
            </div>
          </fieldset>
        )}

        <button className="btn btn--block" disabled={!canSave || saving} onClick={save}>
          {saving ? t('common.saving') : t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
